from eth_utils import decode_hex, to_checksum_address

def get_constructor_arguments(bytecode):
    # Assuming the constructor has a single address parameter (20 bytes)
    address_length = 40
    address_start = -address_length
    
    # Extract the address from the bytecode
    encoded_address = bytecode[address_start:]
    
    # Decode the address
    decoded_address = decode_hex(encoded_address)
    
    # Convert to checksum address
    uni_router_address = to_checksum_address(decoded_address)
    
    return uni_router_address

# Replace this with your actual contract creation bytecode
contract_creation_bytecode = ""

# Remove the "0x" prefix if it exists
if contract_creation_bytecode.startswith("0x"):
    contract_creation_bytecode = contract_creation_bytecode[2:]

uni_router_address = get_constructor_arguments(contract_creation_bytecode)
print(f"Uniswap Router Address: {uni_router_address}")
